from fractions import Fraction
import random

# Claim under test: "yes". Proof idea: if A and B are completely separated, pick a
# continuous h: X -> [0,1] with h = 0 on A and h = 1 on B. Then
#     g = (1 - h) * f1 + h * f2
# is continuous (sums and products of continuous real functions), g = f1 on A,
# and g = f2 on B. This script checks the algebraic identity on random finite
# instances. It samples only; it does not prove the universal topological claim.

def build_and_check(points, A, B, f1, f2, h):
    for p in points:
        if not (Fraction(0) <= h[p] <= Fraction(1)):
            return False, "h out of [0,1]"
    for p in A:
        if h[p] != 0:
            return False, "h not 0 on A"
    for p in B:
        if h[p] != 1:
            return False, "h not 1 on B"
    g = {p: (1 - h[p]) * f1[p] + h[p] * f2[p] for p in points}
    ok_A = all(g[p] == f1[p] for p in A)
    ok_B = all(g[p] == f2[p] for p in B)
    if ok_A and ok_B:
        return True, g
    return False, "interpolation failed"

def random_instance(rng, n):
    points = list(range(n))
    rng.shuffle(points)
    k = rng.randint(1, n - 2)
    m = rng.randint(1, n - k - 1)
    A = points[:k]
    B = points[k:k + m]
    rest = points[k + m:]
    def rf():
        return Fraction(rng.randint(-20, 20), rng.randint(1, 7))
    f1 = {p: rf() for p in points}
    f2 = {p: rf() for p in points}
    h = {}
    for p in points:
        if p in A:
            h[p] = Fraction(0)
        elif p in B:
            h[p] = Fraction(1)
        else:
            h[p] = Fraction(rng.randint(0, 9), 9)
    return points, A, B, f1, f2, h

def main():
    rng = random.Random(0)
    trials = 2000
    passes = 0
    first_fail = None
    for t in range(trials):
        n = rng.randint(4, 9)
        points, A, B, f1, f2, h = random_instance(rng, n)
        ok, info = build_and_check(points, A, B, f1, f2, h)
        if ok:
            passes += 1
        elif first_fail is None:
            first_fail = (t, info)

    print("trials:", trials)
    print("passes:", passes)
    print("first failure:", first_fail)
    print("note: finite random sampling only; continuity follows from the identity")

    if passes == trials:
        print("CHECK PASS")
    else:
        print("CHECK FAIL")

    print("CHECK UNKNOWN: universal topological statement (Tychonoff/continuity) not settled by computation")

if __name__ == "__main__":
    main()
